def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= yy < h and 0 <= xx < w and
                        (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            comps.append((color, cells))

    # Select the longest thin component as the color marker.
    def thinness(cells):
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        return max(max(ys)-min(ys)+1, max(xs)-min(xs)+1) / len(cells)

    marker_color, marker = max(
        comps, key=lambda item: (len(item[1]) * thinness(item[1]), len(item[1]))
    )
    # Find the nearest distinct object and recolor it to the marker color.
    best = None
    for color, cells in comps:
        if cells is marker:
            continue
        dist = min(abs(y-a) + abs(x-b) for y, x in cells for a, b in marker)
        key = (dist, -len(cells))
        if best is None or key < best[0]:
            best = (key, cells)

    if best:
        for y, x in best[1]:
            out[y][x] = marker_color
    return out
